  const n = nums.length;
  const left = new Array(n).fill(1);    // product of everything left of i
  const right = new Array(n).fill(1);   // product of everything right of i
  for (let i = 1; i < n; i++) left[i] = left[i - 1] * nums[i - 1];
  for (let i = n - 2; i >= 0; i--) right[i] = right[i + 1] * nums[i + 1];
  return nums.map((_, i) => left[i] * right[i]);
